insert into public.site_content (key, data) values ('settings', $json${"name":"RizSync Service Solution","shortName":"RizSync","legalName":"RizSync Service Solution","tagline":"Connect • Simplify • Protect • Transform • Grow","description":"RizSync is a multi-disciplinary platform providing expert corporate services, government assistance, and digital transformation, guided by the Quranic business model of trust and integrity.","founded":"2021","copyrightStartYear":2021,"ethicsStatement":"RizSync operates on principles of transparency, integrity, and justice, guided by ethical business practices and the Quranic Business Model.","heroImage":"/images/hero/hero-bg.webp","contact":{"email":"PalzaPast.service@gmail.com","phoneDisplay":"+880 1711-504625","phoneNumber":"8801711504625","whatsappNumber":"8801711504625","whatsappMessage":"Assalamu Alaikum, I'd like to request a consultation with RizSync.","hours":"Mon–Sat, 10am–7pm","openingHoursSchema":"Mo-Sa 10:00-19:00"},"offices":{"corporate":{"label":"Corporate Office","street":"137/10, Mazar Road","locality":"Mirpur","region":"Dhaka","country":"BD"},"operations":{"label":"Business Operation Office","street":"8E/A, 1st Colony, Mazar Road","locality":"Mirpur","region":"Dhaka","country":"BD"}},"mapEmbedSrc":"https://www.google.com/maps?q=137/10%20Mazar%20Road,%20Mirpur,%20Dhaka,%20Bangladesh&output=embed","mapDirectionsUrl":"https://www.google.com/maps/dir/?api=1&destination=137%2F10%20Mazar%20Road%2C%20Mirpur%2C%20Dhaka%2C%20Bangladesh","social":{"facebook":"https://www.facebook.com/RizSync.BD.Official/","linkedin":"","instagram":"","youtube":"","x":"","tiktok":""}}$json$::jsonb) on conflict (key) do nothing;

insert into public.site_content (key, data) values ('home', $json${"hero":{"badge":{"pill":"Ethical","text":"Guided by the Quranic Business Model"},"title":"RizSync {orange:Service} {teal:Solution}","lead":"Your unified professional partner for business & family — corporate compliance, government liaison, finance and digital transformation, under one trusted roof.","motto":[{"word":"Connect","color":"teal"},{"word":"Simplify","color":"orange"},{"word":"Protect","color":"teal"},{"word":"Transform","color":"orange"},{"word":"Grow","color":"gold"}],"primaryCta":"Request Consultation","whatsappCta":"WhatsApp Us","socialProof":"Trusted by entrepreneurs, SMEs, corporates & families since 2021"},"about":{"eyebrow":"Who we are","title":"One partner for every professional matter — handled with {orange:integrity}.","body":"Since 2021, RizSync has helped entrepreneurs, companies and families in Dhaka get their compliance, government and financial matters done — properly, on time, and without the runaround. One team holds the whole picture, so you explain your situation once.","points":[{"label":"Vision","text":"Bangladesh's most trusted platform connecting business support with personal welfare."},{"label":"Mission","text":"Simplify regulatory, financial and digital complexity through expert, ethical advice."},{"label":"Values","text":"Justice, trust, transparency and real benefit in every engagement."}],"cta":"More About RizSync","sinceYear":"2021","sinceLabel":"Serving Dhaka's businesses & families since","confidential":"100% Confidential","photo":"/images/team/about-office.webp","photoAlt":"A RizSync advisor at a desk overlooking the city skyline"},"pillarsSection":{"eyebrow":"Our services","title":"Six pillars of expertise. One seamless experience.","cta":"All Services"},"benefitsSection":{"eyebrow":"Why RizSync","title":"Less paperwork. Less waiting. {gold:More growth.}","body":"We handle the filings, the queues and the follow-ups — so you can put your time into the business and the people who depend on it."},"valuesSection":{"eyebrow":"Our ethical foundation","title":"The Quranic Business Model","body":"Four principles decide how we quote, what we take on and how your information is held.","link":"Read about our values"},"processSection":{"eyebrow":"How we work","title":"From first call to finished file — in 4 steps"},"testimonialsSection":{"eyebrow":"Client voices","title":"What our clients say"},"ctaBanner":{"title":"Ready for an ethical partnership?","body":"Start with a free, confidential consultation. You will leave it knowing exactly what needs doing — and what it will cost.","cta":"Request Consultation"},"insightsSection":{"eyebrow":"Insights","title":"Latest updates & guidance","cta":"View all insights"},"consultationSection":{"eyebrow":"Request consultation","title":"Let's simplify your business & family matters.","body":"Tell us what you need. The first conversation is free and carries no obligation.","submit":"Send Request"},"benefits":[{"title":"Significant Time Savings","description":"We take on the queues, follow-ups and resubmissions so you do not have to.","icon":"Clock","color":"teal"},{"title":"Economy Saving","description":"One integrated partner instead of separate agents — and far fewer penalties.","icon":"Wallet","color":"orange"},{"title":"Expert Documentation","description":"Files prepared to the standard the office, bank or auditor actually expects.","icon":"FileCheck","color":"gold"},{"title":"Tech Back-Office","description":"Digital records and tracked workflows, so you always know where a matter stands.","icon":"Server","color":"teal"}],"processSteps":[{"title":"Consultation","description":"A free, confidential conversation to understand your situation and what actually needs to happen.","color":"navy"},{"title":"Transparent Quote","description":"A written scope, a fixed fee and a realistic timeline — agreed before any work begins.","color":"teal"},{"title":"Execution","description":"Our specialists do the work and prepare every document, updating you at each milestone.","color":"orange"},{"title":"Ongoing Support","description":"You receive the completed file with receipts, plus a calendar of what comes due next.","color":"gold"}]}$json$::jsonb) on conflict (key) do nothing;

insert into public.site_content (key, data) values ('about', $json${"hero":{"eyebrow":"About Us","title":"About RizSync","description":"Simplifying complexity, ethically.","image":"/images/page-heroes/about.webp"},"story":{"eyebrow":"Our Story","title":"Founded in Mirpur, Built on One Observation","body":"RizSync began in 2021 with a simple observation about doing business in Bangladesh: the hard part is rarely the work itself. It is the number of separate people you have to hold together to get anything finished — one for the books, another for the filings, a third for the licence, and nobody with the whole picture.\n\nOur founders had spent years on the other side of that: watching capable businesses lose weeks to resubmissions, and families lose months to documentation nobody had explained. The gap was not expertise. It was coordination, and a standard of conduct you could rely on when you were not in the room.\n\nSo we built one practice across six disciplines — finance, corporate, government liaison, digital operations and family welfare — under a single ethical framework. From our offices on Mazar Road in Mirpur, we now act for entrepreneurs, SMEs, corporate groups and families across Dhaka and beyond.","image":"/images/about-story.webp","imageAlt":"The RizSync mark set within a circuit and geometric lattice motif"},"direction":{"eyebrow":"Direction","title":"Where We Are Going, and How"},"vision":{"title":"Our Vision","text":"To be Bangladesh’s most trusted platform connecting professional business support with personal welfare."},"mission":{"title":"Our Mission","text":"To empower organizations and individuals by simplifying regulatory, financial, and digital complexities through expert, human-centric, and ethical advisory."},"valuesSection":{"eyebrow":"Our Values","title":"The Quranic Business Model","description":"Our operations are guided by principles of Islamic business ethics, ensuring:"},"values":[{"arabic":"عدل","transliteration":"Adl","accent":"teal","english":"Justice","short":"Fair dealing for every client, on every engagement, whatever its size.","long":"Justice means the same standard of care for a sole trader and a corporate group, fees that reflect the work actually performed, and advice that serves your interest even when another course would earn us more. Where a service you have asked for would not benefit you, we say so."},{"arabic":"أمانة","transliteration":"Amanah","accent":"gold","featured":true,"english":"Trust","short":"Your documents and information are held as a trust, never as an asset.","long":"Every document you give us is held under NDA-level confidentiality. Files are accessible only to the named specialists on your engagement, originals are handed over and returned under written acknowledgement, and nothing about your affairs is discussed outside the engagement — including with other clients in your industry."},{"arabic":"شفافية","transliteration":"Shaffafiyyah","accent":"orange","english":"Transparency","short":"Scope, fee and timeline agreed in writing before any work begins.","long":"You receive a written scope, a fixed fee and a realistic timeline before we start. Government fees are passed through at the published rate with the original receipt attached. If something will take longer or cost more, you hear it from us early — not on the invoice."},{"arabic":"نفع","transliteration":"Naf’ah","accent":"gold","english":"Benefit","short":"Work is measured by the benefit it delivers, not the hours it fills.","long":"We recommend the smallest intervention that solves the problem. If a clearer process removes the need for a system, we will tell you. Our measure of a good engagement is whether your position improved — in time saved, risk reduced or clarity gained — not how much of it we performed."}],"teamSection":{"eyebrow":"Leadership","title":"The People Accountable for Your File","description":"The specialists who lead each practice area — and who answer for the work done on your behalf."},"cta":{"title":"Work with a partner you can hold to a standard","description":"Start with a free consultation. You will leave it knowing what needs doing — and whether you need us to do it."}}$json$::jsonb) on conflict (key) do nothing;

insert into public.services (slug, sort_order, title, short_title, h1, nav_description, intro, color, icon, bullets, hero_card, items, why_rizsync, faqs, seo_title, seo_description, seo_keywords)
select slug, sort_order, title, short_title, h1, nav_description, intro, color, icon, bullets, hero_card, items, why_rizsync, faqs, seo_title, seo_description, seo_keywords
from jsonb_to_recordset($json$[{"slug":"finance-accounting","sort_order":0,"title":"Finance, Accounting & Business Support","short_title":"Finance & Accounting","h1":"Professional Finance, Accounting & Business Support","nav_description":"Tax, VAT, treasury and reporting handled by qualified specialists.","intro":"Accurate books, compliant filings and clear numbers you can actually make decisions on. We run the finance function so you can run the business.","color":"teal","icon":"BarChart3","bullets":["Tax & VAT Compliance","Treasury Operations","Cash Flow Management","Financial Reporting & Advisory"],"hero_card":null,"items":[{"title":"Tax & VAT Compliance","description":"Monthly VAT returns, withholding schedules and annual income tax filings prepared, reconciled and submitted on time — with every supporting document retained."},{"title":"Treasury Operations","description":"Day-to-day banking, payment runs, bank reconciliations and Bangladesh Bank correspondence, managed under clear approval limits you set."},{"title":"Cash Flow Management","description":"Rolling 13-week cash forecasts, receivable follow-up and payable scheduling so you always know what is landing and when."},{"title":"Financial Reporting & Advisory","description":"Monthly management accounts, variance commentary and year-end statements prepared to a standard your bank and auditor will accept."},{"title":"Expert Documentation","description":"Vouchers, ledgers, schedules and audit files kept complete and indexed, so an inspection or due-diligence request is never a scramble."}],"why_rizsync":[{"value":"Amanah","text":"Your financial records are treated as a trust. Access is limited to the named specialists on your engagement and every file is held under NDA-level confidentiality."},{"value":"Shaffafiyyah","text":"Fees are quoted before work begins and itemised on every invoice. No percentage-of-savings arrangements, no surprise line items."},{"value":"Adl","text":"We will tell you when a filing position is aggressive, even when a more aggressive position is what you asked for. Compliance first, always."}],"faqs":[{"question":"Can you take over bookkeeping that is already behind?","answer":"Yes. We begin with a catch-up assessment covering the open periods, quantify the work and quote it separately from ongoing monthly support, so you can see exactly what the backlog costs before committing."},{"question":"Which accounting software do you work with?","answer":"We work in Tally, QuickBooks, Xero, Zoho Books and most locally deployed ERP systems. If you have no system yet we will recommend one that matches your transaction volume rather than the most expensive option."},{"question":"Do you handle VAT registration as well as returns?","answer":"We do. That includes BIN registration, VAT 6.3 and 6.1 record-keeping setup, and training one of your staff to maintain the daily registers correctly."},{"question":"Will we still need an external auditor?","answer":"Yes, where an audit is statutorily required. We prepare the books and the audit file; the statutory audit itself must be performed by an independent firm. We coordinate with your auditor throughout."}],"seo_title":"Professional Finance, Accounting & Business Support | RizSync","seo_description":"Expert accounting services in Bangladesh: VAT and corporate tax compliance in Dhaka, treasury, cash flow and financial advisory from Mirpur specialists.","seo_keywords":["Accounting services Bangladesh","Corporate tax Dhaka","Financial advisory Mirpur","VAT compliance Bangladesh"]},{"slug":"business-corporate","sort_order":1,"title":"Business & Corporate Services","short_title":"Business & Corporate","h1":"Strategic Business & Corporate Services","nav_description":"RJSC, company formation, secretarial work and regulatory compliance.","intro":"From incorporation to annual returns, we keep your company legally sound and your statutory records current — without you queuing at a single counter.","color":"orange","icon":"Briefcase","bullets":["RJSC Registration & Filings","Corporate Documentation","Compliance & Regulatory Services","Company Secretarial"],"hero_card":{"title":"Business & Corporate","subtitle":"Trust (Amanah)-based support","chips":["RJSC / Tax & VAT","Bangladesh Bank Filings","Corporate Docs","Compliance"]},"items":[{"title":"RJSC Registration & Filings","description":"Name clearance, memorandum and articles drafting, incorporation, share transfers, director changes and the annual return — filed correctly the first time."},{"title":"Corporate Documentation & Support","description":"Board and shareholder resolutions, statutory registers, minute books and certified copies, drafted to match what the receiving authority actually asks for."},{"title":"Compliance & Regulatory Services","description":"Trade licence, TIN and BIN registration and renewal, fire and environment clearances, and the compliance calendar that keeps every deadline visible."},{"title":"Company Secretarial","description":"Ongoing secretarial retainer: meeting notices, agendas, minutes and filing deadlines managed so the board can focus on decisions rather than paperwork."},{"title":"Bangladesh Bank Filings","description":"Foreign investment reporting, remittance and encashment documentation, and the supporting file the authorised dealer bank will want to see."}],"why_rizsync":[{"value":"Amanah","text":"Incorporation documents, share registers and director identity papers are among the most sensitive files a business owns. Ours never leave a controlled chain of custody."},{"value":"Shaffafiyyah","text":"Government fees are passed through at cost with the original receipt attached. Our service fee is separate and stated up front."},{"value":"Adl","text":"We advise the structure that actually fits your business — not the one with the largest engagement attached to it."}],"faqs":[{"question":"How long does a private limited company registration take?","answer":"Typically two to three weeks from receipt of complete documents: a few days for name clearance, then RJSC submission and certificate issuance. Delays almost always come from incomplete director documentation, which we check before filing."},{"question":"Can a foreign national be a director or shareholder?","answer":"Yes. Foreign shareholding of up to 100% is permitted in most sectors. The additional requirements are passport-based documentation, an encashment certificate for inbound capital, and Bangladesh Bank reporting — all of which we handle."},{"question":"What happens if our annual return is overdue?","answer":"RJSC applies escalating late fees and the company can be flagged as non-compliant, which affects bank facilities and tenders. We can file overdue returns retrospectively and quantify the penalty before you commit."},{"question":"Do you also register partnerships and sole proprietorships?","answer":"We do, including partnership deed drafting and registration, and trade licence applications for proprietorships. We will also tell you plainly when a company structure would serve you better."}],"seo_title":"Strategic Business & Corporate Services | RizSync","seo_description":"Company formation in Bangladesh with expert RJSC assistance: registration, annual filings, documentation and corporate compliance services in Mirpur, Dhaka.","seo_keywords":["Company formation Bangladesh","RJSC assistance","Corporate compliance services","Company registration Dhaka"]},{"slug":"government-assistance","sort_order":2,"title":"Government Service Assistance","short_title":"Government Assistance","h1":"Efficient Government Service Assistance & Liaison","nav_description":"BRTA, city corporation, passport and land matters, navigated ethically.","intro":"Public offices have rules, queues and paperwork. We know all three — and we work inside them, never around them.","color":"teal","icon":"Landmark","bullets":["BRTA Services (Vehicle, License)","DNCC & DSCC Matters","Passport Application & Renewal","Land Fee & Tax Payments"],"hero_card":{"title":"Government Assistance","subtitle":"Ethical bureau-navigation","chips":["BRTA","DNCC / City Corp","Passport & Renewal","Land Fees & Tax"]},"items":[{"title":"BRTA Services","description":"Driving licence issue and renewal, vehicle registration, ownership transfer, fitness and tax token renewal — with the document set checked before the appointment."},{"title":"DNCC & DSCC Matters","description":"City corporation trade licence issue and renewal, holding tax assessment and payment, and signage or occupancy permissions."},{"title":"Passport Application & Renewal","description":"E-passport applications, renewals and reissues: form preparation, fee payment, appointment booking and a checked document file before you attend."},{"title":"Land Fee & Tax Payments","description":"Mutation (namjari) applications, land development tax payment, khatian and porcha collection, and registry office documentation support."},{"title":"Certificate & Attestation Support","description":"Birth and death registration, certificate corrections and notarial attestation, prepared so the receiving office accepts the file on first submission."}],"why_rizsync":[{"value":"Adl","text":"We navigate the official process. We do not offer, arrange or facilitate unofficial payments of any kind, and we will decline work that only succeeds if we do."},{"value":"Shaffafiyyah","text":"Every government fee is quoted at the published rate and receipted to you. What you pay us for is the preparation, the queuing and the follow-up — nothing else."},{"value":"Amanah","text":"Passports, NIDs and land documents are handed over under written acknowledgement and returned the same way."}],"faqs":[{"question":"Do I have to attend in person for BRTA or passport services?","answer":"For biometric enrolment and the driving test, yes — those cannot be delegated. Everything around them (forms, fees, appointment booking, document verification, collection) we handle, so your one visit is short and successful."},{"question":"How do you speed things up if you do not use unofficial channels?","answer":"By removing the two things that actually cause delay: incomplete files and missed steps. Most rejections are documentation errors. We check the file against the current requirement list before submission and follow up on schedule."},{"question":"Can you handle a land mutation for property outside Dhaka?","answer":"In many districts, yes, though timelines vary by AC Land office. Tell us the district and mouza at the consultation and we will confirm coverage and a realistic timeline before quoting."},{"question":"What if an application is rejected?","answer":"We obtain the written reason, correct the file and resubmit. Where the rejection was caused by our preparation error, the resubmission is at our cost."}],"seo_title":"Efficient Government Service Assistance & Liaison | RizSync","seo_description":"BRTA licence renewal in Dhaka, DNCC services, trade licence assistance and land mutation in Bangladesh — ethical government liaison from RizSync, Mirpur.","seo_keywords":["BRTA license renewal Dhaka","DNCC services","Land mutation Bangladesh","Trade license assistance"]},{"slug":"digital-transformation","sort_order":3,"title":"Digital & Business Transformation","short_title":"Digital Transformation","h1":"Digital Transformation & Business Process Outsourcing (BPO)","nav_description":"Automation, ERP support, cloud and AI, and a reliable back office.","intro":"Technology should remove work, not add a second system to maintain. We automate the repetitive parts of your operation and run what is left.","color":"orange","icon":"Cpu","bullets":["Digital Process Automation","ERP & Accounting System Support","Cloud Services & AI Integration","Back-Office Optimization"],"hero_card":null,"items":[{"title":"Digital Process Automation","description":"We map the process first, remove the steps that exist only out of habit, then automate what remains — approvals, reminders, reconciliations and reporting."},{"title":"ERP & Accounting System Support","description":"Selection, implementation, chart-of-accounts design, data migration and staff training for Tally, Zoho, QuickBooks, Xero and mainstream ERP platforms."},{"title":"Cloud Services & AI Integration","description":"Migration to managed cloud storage and email, secure document workflows, and practical AI assistance for document handling, drafting and customer response."},{"title":"Back-Office Optimization","description":"Dedicated offshore-standard back-office support for data entry, invoice processing, reconciliation and customer administration, on your systems and your controls."},{"title":"Tech Back-Office as a Service","description":"A named team, agreed service levels and monthly reporting — the capability of an in-house operations department without the fixed headcount."}],"why_rizsync":[{"value":"Naf’ah","text":"We recommend the smallest change that produces the benefit. If a spreadsheet and a clear process solve it, we will not sell you a platform."},{"value":"Amanah","text":"Your data stays yours. Credentials are held in a managed vault, access is role-based and revoked on staff change, and exports are available on request at any time."},{"value":"Shaffafiyyah","text":"Licence costs, one-off implementation fees and the monthly retainer are quoted as three separate numbers, so you can see what is software and what is us."}],"faqs":[{"question":"We already have software nobody uses. Can that be fixed?","answer":"Usually, yes — and more cheaply than replacing it. Low adoption is normally a configuration and training problem, not a product problem. We start with a two-week review before recommending any change of platform."},{"question":"Is our data safe if the back office is outsourced?","answer":"Access is role-based and logged, staff sign individual confidentiality undertakings, and work is performed on your systems wherever possible so the data never leaves your control."},{"question":"How quickly does automation pay for itself?","answer":"For document-heavy processes such as invoice handling and reconciliation, most clients see the implementation cost recovered within six to twelve months. We put that estimate in writing in the quote, with the assumptions shown."},{"question":"Do you build custom software?","answer":"We integrate and configure established platforms, and build light custom tooling where no product fits. We will say clearly when a requirement needs a full development partner rather than us."}],"seo_title":"Digital Transformation & Business Process Outsourcing (BPO) | RizSync","seo_description":"BPO services in Dhaka and digital transformation in Bangladesh: process automation, cloud integration and accounting software support from RizSync, Mirpur.","seo_keywords":["BPO services Dhaka","Digital transformation Bangladesh","Cloud integration for business","Accounting software support"]},{"slug":"family-welfare","sort_order":4,"title":"Family Welfare & Services","short_title":"Family Welfare","h1":"Holistic Family Welfare & Financial Planning","nav_description":"Family financial planning, wealth advisory and long-term security.","intro":"The same discipline we bring to a balance sheet, applied to a household: what you own, what it must provide for, and how to protect it.","color":"teal","icon":"Home","bullets":["Family Financial Planning","Wealth Assessment & Advisory","Education & Retirement Planning","Long-Term Security Solutions"],"hero_card":null,"items":[{"title":"Family Financial Planning","description":"A clear picture of household income, commitments and savings, turned into a written plan with priorities you and your family have agreed on."},{"title":"Wealth Assessment & Advisory","description":"Consolidation of assets across property, deposits, business interests and savings instruments, with an honest view of concentration and liquidity risk."},{"title":"Education & Retirement Planning","description":"Costing education milestones and retirement income needs in today’s money, then working back to what must be set aside and when."},{"title":"Long-Term Security Solutions","description":"Emergency reserves, protection cover and succession documentation, structured so a family is not left searching for papers at the worst possible time."},{"title":"Family Documentation Support","description":"Wills, nominee records, property papers and the personal government services in our Government Assistance pillar, coordinated in one place."}],"why_rizsync":[{"value":"Amanah","text":"Family financial information is the most private thing a client shares with us. It is held by a named adviser, never pooled, and never used for anything but your plan."},{"value":"Shaffafiyyah","text":"We are paid by you, in fees you agreed in advance. We take no commission from any product provider, so nothing we recommend earns us more than anything else."},{"value":"Naf’ah","text":"Plans are written to serve the family, including the members who are not in the room — spouses, children and dependent parents."}],"faqs":[{"question":"Do you sell insurance or investment products?","answer":"No. We are fee-only advisers. We will help you evaluate a product and negotiate terms, but we receive nothing from any provider, which is what keeps the advice honest."},{"question":"Can planning be structured on Shariah-compliant principles?","answer":"Yes, and for many clients this is the starting point. We can build plans that avoid interest-bearing instruments and work within Islamic finance structures available in Bangladesh, and we will be clear about where options are limited."},{"question":"Is there a minimum level of wealth to work with you?","answer":"No. A first consultation and a written plan are useful at any level, and are often most valuable to families who are still building. Ongoing advisory retainers are sized to the work involved."},{"question":"Will you work with our whole family?","answer":"We encourage it. Plans that only one family member understands tend to fail exactly when they are needed, so we prefer at least two adults in the review meetings."}],"seo_title":"Holistic Family Welfare & Financial Planning | RizSync","seo_description":"Personal financial planning in Dhaka and wealth advisory in Bangladesh: education, retirement and family security solutions from fee-only RizSync advisers.","seo_keywords":["Personal financial planning Dhaka","Wealth advisory Bangladesh","Family security solutions","Islamic financial planning Bangladesh"]},{"slug":"why-rizsync","sort_order":5,"title":"Benefits & Value Proposition","short_title":"Benefits & Value","h1":"Why Choose RizSync? Our Value Proposition","nav_description":"What changes for you when one ethical partner holds it all.","intro":"Six specialisms, one relationship, one standard of conduct. Here is what that is actually worth to a business or a family.","color":"gold","icon":"Award","bullets":["Significant Time Savings","Expert Documentation","Trusted Partner for Business & Family","Integrated & Seamless Service"],"hero_card":{"title":"Benefits & Value","subtitle":"Just value delivery","chips":["Time Savings","Economy Saving","Expert Documentation","Tech Back-Office"]},"items":[{"title":"Significant Time Savings","description":"The hours a founder loses to queues, resubmissions and chasing status updates are the most expensive hours in the business. We absorb them."},{"title":"Economy Saving","description":"One integrated retainer instead of separate accountant, agent and consultant fees — and far fewer penalties, because deadlines are tracked rather than remembered."},{"title":"Expert Documentation","description":"Files prepared to the standard the receiving office, bank or auditor expects, which is the single biggest determinant of whether something is accepted first time."},{"title":"Trusted Partner for Business & Family","description":"The same team that files your company return can help with a passport renewal or a family plan. You explain your situation once."},{"title":"Integrated & Seamless Service","description":"One point of contact, one file, one set of standards across all six pillars — no handoffs where information gets lost."},{"title":"Tech-Enabled Back Office","description":"Digital document handling and tracked workflows mean you can see where something stands without having to ask."}],"why_rizsync":[{"value":"Adl","text":"Just value delivery: what you are charged reflects the work performed, and we will tell you when a service you have asked for is not worth buying."},{"value":"Amanah","text":"One partner holding business and family matters means one place where confidentiality has to hold. We treat that as the core of the relationship."},{"value":"Shaffafiyyah","text":"Scope, fee and timeline are agreed in writing before work begins, and changes to any of the three are agreed the same way."}],"faqs":[{"question":"What makes RizSync different from a regular consultancy?","answer":"Two things: the range — finance, corporate, government, digital and family matters under one roof — and the conduct standard behind it. We operate on a stated ethical framework and decline work that requires us to depart from it."},{"question":"Do I have to use all six pillars?","answer":"Not at all. Most clients start with one pressing problem. The integration matters when the second need appears, because we already know your situation."},{"question":"How is pricing structured?","answer":"One-off work is quoted as a fixed fee after a free consultation. Ongoing support is a monthly retainer sized to scope. Government fees are always passed through at cost with receipts."},{"question":"What does the first consultation involve?","answer":"A conversation of about forty-five minutes, at no cost and with no obligation, to understand the situation. You leave it with our honest view of what needs doing — including when the answer is that you do not need us."}],"seo_title":"Why Choose RizSync? Our Value Proposition | RizSync","seo_description":"A professional services platform in Dhaka built on ethics: real time savings, expert documentation and one trusted business partner in Bangladesh, Mirpur.","seo_keywords":["Professional services platform Dhaka","Trusted business partner Bangladesh","Integrated business services Dhaka"]}]$json$::jsonb) as x(slug text, sort_order int, title text, short_title text, h1 text, nav_description text, intro text, color text, icon text, bullets text[], hero_card jsonb, items jsonb, why_rizsync jsonb, faqs jsonb, seo_title text, seo_description text, seo_keywords text[])
on conflict (slug) do nothing;

insert into public.insights (slug, title, excerpt, category, tags, author, published_on, cover, featured, content)
select slug, title, excerpt, category, tags, author, published_on, cover, featured, content
from jsonb_to_recordset($json$[{"slug":"rjsc-annual-return-checklist","title":"The RJSC Annual Return: A Director’s Checklist","excerpt":"The annual return is the filing most often forgotten and the one most likely to hold up a bank facility. What it requires, when it is due, and what happens if it is late.","category":"RJSC & Compliance","tags":["RJSC","Company Law","Annual Return","Governance"],"author":"RizSync Advisory Team","published_on":"2026-07-02","cover":"/images/insights/rjsc-return-photo.webp","featured":false,"content":"Of all the obligations a Bangladeshi private limited company carries, the annual return to the Registrar of Joint Stock Companies and Firms is the one most often discovered late — usually by a bank, a prospective investor or a tender committee rather than by the company itself.\n\nIt is also one of the easier ones to keep current, provided the underlying records exist.\n\n> **Note.** Requirements and timelines change. Treat this as an orientation, and confirm the current position before filing.\n\n## What the annual return is for\n\nThe return is the public record of who owns and runs the company. It tells anyone who looks — a bank, a counterparty, a regulator — the current share capital, the shareholders, the directors and the registered office.\n\nThat is precisely why a stale return causes friction. A lender performing diligence sees a register that does not match what you have told them, and the conversation stops until it is corrected.\n\n## What you need before you file\n\nThree sets of records, and the filing is straightforward when they are current:\n\n### 1. The statutory registers\n\n- Register of members, reflecting every share transfer that has actually happened\n- Register of directors, with the dates of every appointment and resignation\n- Register of charges, if the company has given any security\n\n### 2. Board and general meeting records\n\nThe notices, attendance and signed minutes for the annual general meeting, plus any resolutions passed during the year that changed the directors, the capital or the constitution.\n\n### 3. The financial statements\n\nThe accounts laid before the members, in the form in which they were adopted.\n\nWhere companies come unstuck is not the form itself — it is discovering that a share transfer agreed eighteen months ago was never recorded, or that a director who left never formally resigned.\n\n## Keeping it current instead of reconstructing it\n\nThe reconstruction work is always more expensive than the maintenance work. A practical rhythm:\n\n1. **Record the event when it happens.** A resignation, a transfer or an allotment goes into the register the week it occurs, not the week before filing.\n2. **Keep one calendar of statutory dates.** The annual general meeting, the return and the tax filings sit on the same calendar, visible to more than one person.\n3. **Review the registers once a quarter.** Fifteen minutes against the board minutes catches divergence while it is still trivial.\n\n## If the return is overdue\n\nLate filing attracts escalating fees, and a prolonged gap can leave the company flagged as non-compliant — which is what causes the bank problem.\n\nOverdue returns can generally be filed retrospectively. The sensible order is to establish which years are outstanding, reconstruct the register position for each, quantify the fees, and then file from the oldest year forward so the record becomes internally consistent.\n\n## The underlying point\n\nThe annual return is a mirror. It is difficult only when the thing it reflects — the company's own record of itself — has drifted. Keep the registers honest as events happen and the filing becomes administrative.\n\nIf you are not certain when your company last filed, that is worth checking today rather than the week a lender asks."},{"slug":"vat-return-deadlines-bangladesh","title":"Monthly VAT Returns: What Actually Causes a Late Filing","excerpt":"Most VAT penalties are not caused by a lack of money — they are caused by a missing document on the fifteenth. Here is the sequence that keeps returns on time.","category":"Tax & VAT","tags":["VAT","NBR","Compliance","Mushak"],"author":"RizSync Advisory Team","published_on":"2026-08-18","cover":"/images/insights/vat-returns-photo.webp","featured":true,"content":"Every registered business in Bangladesh files a monthly VAT return with the National Board of Revenue. The rule itself is simple. The reason so many businesses still file late is almost never the rule — it is that the supporting records were not ready when the deadline arrived.\n\nThis is a practical note on where those delays come from and how to remove them.\n\n> **Note.** This article is general guidance, not advice on your specific position. Rates, forms and deadlines change. Confirm the current requirement before you rely on anything here.\n\n## Why the deadline is not the problem\n\nThe filing date is fixed and known months in advance. What varies is the state of your records on the day before it.\n\nIn our experience the same three gaps account for most late or amended returns:\n\n1. **Purchase documentation arriving after the cut-off.** A supplier's invoice reaches accounts on the twentieth, so the input claim either misses the period or forces an amendment later.\n2. **Registers maintained after the fact.** Sales and purchase registers written up from bank statements at month end rather than from source documents as they occur.\n3. **One person holding the whole process.** When the deadline depends on one individual's availability, illness or travel becomes a compliance event.\n\nNone of these are accounting problems. They are process problems, and they are fixable without new software.\n\n## A working monthly sequence\n\nThe businesses that never file late tend to run something close to this rhythm.\n\n### Days 1–5: close the source records\n\nPost every sales and purchase document for the previous month from the document itself, not from the bank feed. Anything missing is chased now, while the supplier still remembers the transaction.\n\n### Days 6–10: reconcile\n\nMatch the VAT registers to the general ledger and to the bank. Differences found here are cheap. Differences found after submission are an amendment, and amendments attract attention.\n\n### Days 11–13: prepare and review\n\nDraft the return and have a second person review it against the registers. The reviewer's job is not to redo the work — it is to ask why any figure moved sharply against the prior month.\n\n### Day 14: submit\n\nSubmitting a day early is not caution, it is margin. Portals are slowest on the final day, and a technical failure on the deadline is still a late filing.\n\n## What to do if you are already behind\n\nFiling late is better than not filing. Penalties accrue on the outstanding position, and a visible pattern of non-filing is a far worse starting point for any negotiation than a late but complete record.\n\nThe order of work is:\n\n- Establish exactly which periods are open, and for each one what is missing.\n- Quantify the likely penalty before deciding anything, so the decision is made on numbers rather than on anxiety.\n- Bring the oldest period to a filable state first. Momentum matters, and the oldest period is usually the one accruing the most.\n\n## The underlying point\n\nCompliance is a documentation discipline far more than it is a tax one. Businesses that treat the VAT register as something written up at month end will always be at the mercy of whoever has the missing invoice. Businesses that treat it as a daily record rarely think about the deadline at all.\n\nIf your returns are behind, or the monthly close depends on one person, that is worth a conversation before the next deadline rather than after it."},{"slug":"what-makes-a-business-ethical","title":"What an Ethical Business Model Looks Like in Daily Practice","excerpt":"Adl, Amanah, Shaffafiyyah and Naf’ah are easy to put on a website. This is what they mean when a client asks you to do something you should not.","category":"Islamic Finance","tags":["Ethics","Islamic Business","Governance","Trust"],"author":"RizSync Advisory Team","published_on":"2026-06-11","cover":"/images/insights/ethics-photo.webp","featured":false,"content":"Any firm can publish a values page. The question worth asking of a professional adviser is narrower and more useful: what do those values cost you, and when?\n\nOur practice is built on four principles drawn from the Quranic business model. Here is what each one actually decides.\n\n## Adl — justice\n\nJustice is mostly about fees and candour.\n\nIn practice it means the same standard of care regardless of engagement size, and it means saying so when a service you have asked us to perform will not benefit you. Telling a client that the work they came for is unnecessary costs revenue in the short run. It is also the only basis on which advice is worth taking.\n\nIt also decides what we will not do. A filing position that is defensible is worth discussing; one that is not, is not — however the client feels about it.\n\n## Amanah — trust\n\nAmanah is the principle with the most operational consequence, because it is about documents.\n\nConcretely: files are accessible only to the named specialists on an engagement, not to the firm generally. Original documents — passports, deeds, certificates — move under written acknowledgement in both directions. Nothing about a client's affairs is discussed outside the engagement, including with other clients in the same industry, and particularly not as a demonstration of expertise.\n\nThe uncomfortable version of Amanah is that it holds after a relationship ends, and when the client is no longer in a position to check.\n\n## Shaffafiyyah — transparency\n\nTransparency means the numbers are agreed before the work, not after it.\n\nScope, fee and timeline go in writing first. Government fees are passed through at the published rate with the original receipt attached, never marked up and never bundled into a single opaque figure. When something will take longer or cost more, the client hears it early — which is the only point at which the information is useful.\n\nIn government-facing work transparency has a harder edge: we do not offer, arrange or facilitate unofficial payments, and we decline work that can only succeed if we do. That costs us engagements. It is not negotiable, because a firm that makes the exception once has no principle left to offer the next client.\n\n## Naf’ah — benefit\n\nBenefit means the smallest intervention that solves the problem.\n\nA firm paid by volume has a structural reason to recommend more work. We try to measure an engagement by whether the client's position actually improved — time saved, risk reduced, clarity gained — rather than by how much of it we performed. If a clearer process removes the need for a system, we say so, even though the system would have been the larger engagement.\n\n## Why this is a business argument, not only a moral one\n\nClients rarely leave an adviser over price. They leave over the discovery that they were not told something.\n\nThe four principles above are, read commercially, a description of how not to lose clients: charge what you said, tell people what they need to know when it is still actionable, hold their information properly, and do not sell them work they do not need.\n\nThat they also happen to be an obligation is, for us, the point."}]$json$::jsonb) as x(slug text, title text, excerpt text, category text, tags text[], author text, published_on date, cover text, featured boolean, content text)
on conflict (slug) do nothing;

insert into public.team_members (name, title, bio, photo, linkedin, email, sort_order)
select name, title, bio, photo, linkedin, email, sort_order from jsonb_to_recordset($json$[{"name":"Placeholder Name","title":"Founder & Managing Director","bio":"Placeholder biography. Two to three lines covering professional background, qualifications and the areas of the practice this person leads.","photo":null,"linkedin":null,"email":null,"sort_order":0},{"name":"Placeholder Name","title":"Head of Finance & Compliance","bio":"Placeholder biography. Two to three lines covering professional background, qualifications and the areas of the practice this person leads.","photo":null,"linkedin":null,"email":null,"sort_order":1},{"name":"Placeholder Name","title":"Head of Corporate Services","bio":"Placeholder biography. Two to three lines covering professional background, qualifications and the areas of the practice this person leads.","photo":null,"linkedin":null,"email":null,"sort_order":2},{"name":"Placeholder Name","title":"Head of Digital Transformation","bio":"Placeholder biography. Two to three lines covering professional background, qualifications and the areas of the practice this person leads.","photo":null,"linkedin":null,"email":null,"sort_order":3}]$json$::jsonb) as x(name text, title text, bio text, photo text, linkedin text, email text, sort_order int)
where not exists (select 1 from public.team_members);

insert into public.testimonials (quote, name, role, company, rating, sort_order)
select quote, name, role, company, rating, sort_order from jsonb_to_recordset($json$[{"quote":"We had three separate people handling tax, RJSC filings and licence renewals, and none of them spoke to each other. RizSync took all of it. The first thing they did was show us a calendar of every deadline we had been missing.","name":"Placeholder Name","role":"Managing Director","company":"Placeholder Trading Ltd.","rating":5,"sort_order":0},{"quote":"What I value most is being told plainly when something is not worth doing. They talked us out of a software purchase we had already budgeted for, and fixed the process instead.","name":"Placeholder Name","role":"Founder","company":"Placeholder Apparel","rating":5,"sort_order":1},{"quote":"They handled my father’s land mutation and my company’s annual return in the same month, and I only had to explain our family situation once. Every fee came with the government receipt attached.","name":"Placeholder Name","role":"Director","company":"Placeholder Group","rating":5,"sort_order":2}]$json$::jsonb) as x(quote text, name text, role text, company text, rating int, sort_order int)
where not exists (select 1 from public.testimonials);

insert into public.faqs (question, answer, sort_order)
select question, answer, sort_order from jsonb_to_recordset($json$[{"question":"How does an engagement with RizSync start?","answer":"With a free consultation of about forty-five minutes, in person at our Mirpur office, by phone or over WhatsApp. We listen to the situation, tell you honestly what needs doing, and follow up with a written scope and fixed quote. Nothing begins until you accept it.","sort_order":0},{"question":"Do you work with individuals as well as companies?","answer":"Yes. Roughly half of our work is for businesses — accounting, RJSC, compliance, digital operations — and the rest is personal and family: government services, documentation and financial planning. Many clients use us for both.","sort_order":1},{"question":"How is pricing structured?","answer":"One-off work is a fixed fee quoted before we start. Ongoing support is a monthly retainer sized to the agreed scope. Government fees are never marked up: they are passed through at the published rate with the original receipt attached to your invoice.","sort_order":2},{"question":"What does the Quranic Business Model mean in practice?","answer":"Four commitments: Adl (justice) — fair dealing and fair fees; Amanah (trust) — your documents held in confidence; Shaffafiyyah (transparency) — scope, fee and timeline in writing before work begins; and Naf’ah (benefit) — the smallest intervention that solves the problem. It also means we decline work that can only succeed through unofficial payments.","sort_order":3},{"question":"How quickly can you start?","answer":"Consultations are usually available within one to two working days. For time-critical matters such as an expiring licence or a filing deadline, tell us when you call and we will prioritise the assessment accordingly.","sort_order":4}]$json$::jsonb) as x(question text, answer text, sort_order int)
where not exists (select 1 from public.faqs);
